def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not cells:
        return out
    top = min(r for r, _ in cells)
    bottom = max(r for r, _ in cells)
    left = min(c for _, c in cells)
    right = max(c for _, c in cells)

    for r in range(h):
        for c in range(w):
            if out[r][c] == 6:
                out[r][c] = 0

    for r in range(top, bottom + 1):
        target_r = bottom + 1 + (bottom - r)
        if target_r < h:
            for c in range(left, right + 1):
                if grid[r][c] == 4:
                    out[target_r][c] = 4
    return out
